create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', payday integer not null default 1 check(payday between 1 and 31), theme text not null default 'light' check(theme in ('light','dark')), currency text not null default 'BRL', created_at timestamptz not null default now());
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, kind text not null check(kind in ('income','expense')), color text not null default '#0b7a55', icon text not null default 'circle', limit_amount numeric(14,2), created_at timestamptz not null default now());
create table if not exists public.transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, category_id uuid references public.categories(id) on delete set null, kind text not null check(kind in ('income','expense')), description text not null, amount numeric(14,2) not null check(amount>0), transaction_date date not null, payment_method text, note text, critical boolean not null default false, recurring text check(recurring in ('none','weekly','monthly','yearly')) default 'none', cycle_id uuid, created_at timestamptz not null default now());
create table if not exists public.debts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, creditor text not null, total_amount numeric(14,2) not null check(total_amount>0), paid_amount numeric(14,2) not null default 0, installments_total integer, installments_paid integer not null default 0, installment_amount numeric(14,2), due_date date, interest numeric(8,3), created_at timestamptz not null default now());
create table if not exists public.cycles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, starts_on date not null, ends_on date not null, income numeric(14,2) not null default 0, expenses numeric(14,2) not null default 0, critical numeric(14,2) not null default 0, remainder numeric(14,2) not null default 0, archived_at timestamptz not null default now());
create table if not exists public.recurring_templates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, description text not null, amount numeric(14,2) not null, kind text not null check(kind in ('income','expense')), category_id uuid references public.categories(id) on delete set null, payment_method text, critical boolean not null default false, frequency text not null default 'monthly', active boolean not null default true, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.transactions enable row level security; alter table public.debts enable row level security; alter table public.cycles enable row level security; alter table public.recurring_templates enable row level security;
create policy "profile own" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "categories own" on public.categories for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "transactions own" on public.transactions for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "debts own" on public.debts for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "cycles own" on public.cycles for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "recurring own" on public.recurring_templates for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'name','')); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
